private static int frustumWeightedDistance(final ChunkPos playerPos, final float lookX, final float lookZ, final long packedPos) {
      int dx = ChunkPos.getX(packedPos) - playerPos.x();
      int dz = ChunkPos.getZ(packedPos) - playerPos.z();
      int distSqr = dx * dx + dz * dz;
      if (distSqr <= 4) {
         return distSqr;
      }
      float dot = dx * lookX + dz * lookZ;
      if (dot > 0.0F) {
         return distSqr;
      }
      return (dot * dot > 0.25F * distSqr) ? distSqr * 4 : distSqr * 2;
   }

